CREATE OR REPLACE FUNCTION audit.if_modified_func() RETURNS TRIGGER AS $body$
DECLARE
    v_app_user_id INTEGER;
BEGIN
    v_app_user_id := NULLIF(current_setting('audit.app_user_id', true), '')::INTEGER;
    IF (TG_OP = 'UPDATE') THEN
        INSERT INTO audit.logged_actions (schema_name, table_name, op, old_data, new_data, changed_by_user_id)
        VALUES (TG_TABLE_SCHEMA, TG_TABLE_NAME, 'U', to_jsonb(OLD), to_jsonb(NEW), v_app_user_id);
        RETURN NEW;
    ELSIF (TG_OP = 'DELETE') THEN
        INSERT INTO audit.logged_actions (schema_name, table_name, op, old_data, new_data, changed_by_user_id)
        VALUES (TG_TABLE_SCHEMA, TG_TABLE_NAME, 'D', to_jsonb(OLD), NULL, v_app_user_id);
        RETURN OLD;
    ELSIF (TG_OP = 'INSERT') THEN
        INSERT INTO audit.logged_actions (schema_name, table_name, op, old_data, new_data, changed_by_user_id)
        VALUES (TG_TABLE_SCHEMA, TG_TABLE_NAME, 'I', NULL, to_jsonb(NEW), v_app_user_id);
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$body$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public;
